import type { SidebarsConfig } from '@docusaurus/plugin-content-docs';

// This runs in Node.js - Don't use client-side code here (browser APIs, JSX...)

/**
 * Creating a sidebar enables you to:
 - create an ordered group of docs
 - render a sidebar for each doc of that group
 - provide next/previous navigation

 The sidebars can be generated from the filesystem, or explicitly defined here.

 Create as many sidebars as you want.
 */
// The OpenAPI sidebar slices are generated by `docusaurus-plugin-openapi-docs` into `docs/combine-api-3-14/`, `docs/combine-api-3-15/` and `docs/cap-scap-api/` and won't exist on a fresh checkout
const loadApiItems = (outputDir: string): SidebarsConfig[string] => {
  try {
    // eslint-disable-next-line @typescript-eslint/no-require-imports
    return require(`./docs/${outputDir}/sidebar`).default;
  } catch {
    return [];
  }
};

// API reference nested underneath it as a sub-category.
const combineAwsItems: SidebarsConfig[string] = [
  { type: 'autogenerated', dirName: 'Combine-AWS' },
];

const buildApiCategory = (outputDir: string, label: string, title: string, slug: string, description: string) => {
  const apiItems = loadApiItems(outputDir);

  if (!Array.isArray(apiItems) || apiItems.length === 0) {
    return undefined;
  }

  return {
    type: 'category' as const,
    label,
    link: {
      type: 'generated-index' as const,
      title,
      slug,
      description,
    },
    items: apiItems,
  };
};

// The Combine TAP API changes with each Combine release, so it has one sub-category per release line.
const combineApiVersions = [
  buildApiCategory('combine-api-3-14', '3.14.x', 'Combine API 3.14.x', '/category/combine-api-3-14-x', 'Reference for the Combine TAP API in Combine 3.14.x.'),
  buildApiCategory('combine-api-3-15', '3.15.x', 'Combine API 3.15.x', '/category/combine-api-3-15-x', 'Reference for the Combine TAP API in Combine 3.15.x.'),
].filter((category) => category !== undefined);

if (combineApiVersions.length > 0) {
  combineAwsItems.push({
    type: 'category',
    label: 'Combine API',
    link: {
      type: 'generated-index',
      title: 'Combine API',
      slug: '/category/combine-api',
      description: 'Reference for the Combine TAP API, by Combine release.',
    },
    items: combineApiVersions,
  });
}

// The CAP / SCAP API follows the high side customer's update cycle, not Combine's, so it has a single reference.
const capScapApi = buildApiCategory('cap-scap-api', 'CAP / SCAP API', 'CAP / SCAP API', '/category/cap-scap-api', 'Reference for the CAP / SCAP compatible credential API.');

if (capScapApi) {
  combineAwsItems.push(capScapApi);
}

const sidebars: SidebarsConfig = {
  tutorialSidebar: [
    {
      type: 'category',
      label: 'Combine AWS',
      items: combineAwsItems,
    },
    {
      type: 'category',
      label: 'Combine Azure',
      items: [{ type: 'autogenerated', dirName: 'Combine-Azure' }],
    },
  ],
};

export default sidebars;
